/*
 * A059431  Triangle formed when cumulative boustrophedon transform is applied
 *          to 1, 0, 0, 0, ..., read by rows from left to right.
 * https://oeis.org/A059431
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is the row‑by‑row flattened output of the cumulative
 *            Boustrophedon transform of the sequence 1,0,0,0,... The triangle
 *            A059432 is generated by starting with [1] and, for each new row
 *            n>0, making a row of length n+1 whose first element is 0 and
 *            whose subsequent elements are cumulative sums of...
 * Range:     u8 n <= 18, u16 n <= 32, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Static cache of rows of the A059432 triangle. */
    static seq_t **rows = NULL;      /* array of pointers to each row */
    static idx_t  row_count = 0;     /* number of rows currently cached */
    static size_t row_cap   = 0;     /* capacity of the rows[] array */

    /* Find the row i and column j that contain the n‑th flattened term */
    idx_t i = 0;            /* current row index */
    idx_t prefix = 0;       /* number of terms before row i */
    idx_t row_len = 1;       /* length of row i (i+1) */

    while (prefix + row_len <= n) {
        prefix += row_len;  /* include whole current row */
        i++;                /* move to next row */
        row_len = i + 1;    /* new row length */
    }
    idx_t j = n - prefix;   /* column within row i (0 ≤ j ≤ i) */

    /* Ensure that all rows up to i are computed and cached */
    while (row_count <= i) {
        /* Allocate a new row (index = row_count) */
        size_t idx = (size_t)row_count;          /* used for array indexing */

        if (row_count == 0) {
            /* Row 0: single element 1 */
            if (row_cap == 0) {
                row_cap = 1;
                rows = (seq_t **)malloc(sizeof(seq_t *));
            } else if (row_cap < 1) {
                row_cap = 1;
                rows = (seq_t **)realloc(rows, sizeof(seq_t *));
            }
            seq_t *row0 = (seq_t *)malloc(sizeof(seq_t));
            row0[0] = (seq_t)1;
            rows[0] = row0;
        } else {
            /* Create row `row_count` from previous row `row_count-1`. */
            size_t prev_len = (size_t)row_count;          /* length of prev row */
            seq_t *prev  = rows[idx - 1];
            seq_t *cur   = (seq_t *)malloc(sizeof(seq_t) * (row_count + 1));

            cur[0] = (seq_t)0;   /* first element of the new row */

            seq_t cum_rev = (seq_t)0;  /* cumulative sum over reversed prev row */
            seq_t cum_row = (seq_t)0;  /* cumulative sum for current row */

            for (idx_t k = 1; k <= row_count; ++k) {
                seq_t rev_val = prev[prev_len - k];
                cum_rev += rev_val;
                cum_row += cum_rev;
                cur[(size_t)k] = cum_row;
            }

            if (row_count >= row_cap) {
                row_cap = (row_cap == 0) ? 1 : row_cap * 2;
                rows = (seq_t **)realloc(rows, sizeof(seq_t *) * row_cap);
            }
            rows[idx] = cur;
        }

        row_count++;   /* one more row cached */
    }

    /* Retrieve the required element, reversing rows with even i. */
    idx_t col = (i % 2 == 0) ? (i - j) : j;
    return rows[(size_t)i][(size_t)col];
}
